namespace RonSijm.FluidHumidifier.Factories.BedrockAgentCore;

public class RuntimeFactory(string resourceName = null, Action<Humidifier.BedrockAgentCore.Runtime> factoryAction = null) : ResourceFactory<Humidifier.BedrockAgentCore.Runtime>(resourceName)
{

    internal List<InnerRuntimeFilesystemConfigurationFactory> FilesystemConfigurationsFactories { get; set; } = [];

    internal InnerRuntimeLifecycleConfigurationFactory LifecycleConfigurationFactory { get; set; }

    internal InnerRuntimeAgentRuntimeArtifactFactory AgentRuntimeArtifactFactory { get; set; }

    internal InnerRuntimeRequestHeaderConfigurationFactory RequestHeaderConfigurationFactory { get; set; }

    internal InnerRuntimeNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    internal InnerRuntimeCapacityProviderConfigurationFactory CapacityProviderConfigurationFactory { get; set; }

    internal InnerRuntimeAuthorizerConfigurationFactory AuthorizerConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.Runtime Create()
    {
        var runtimeResult = CreateRuntime();
        factoryAction?.Invoke(runtimeResult);

        return runtimeResult;
    }

    private Humidifier.BedrockAgentCore.Runtime CreateRuntime()
    {
        var runtimeResult = new Humidifier.BedrockAgentCore.Runtime
        {
            GivenName = InputResourceName,
        };

        return runtimeResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.Runtime result)
    {
        base.CreateChildren(result);

        result.FilesystemConfigurations = FilesystemConfigurationsFactories.Any() ? FilesystemConfigurationsFactories.Select(x => x.Build()).ToList() : null;
        result.LifecycleConfiguration ??= LifecycleConfigurationFactory?.Build();
        result.AgentRuntimeArtifact ??= AgentRuntimeArtifactFactory?.Build();
        result.RequestHeaderConfiguration ??= RequestHeaderConfigurationFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
        result.CapacityProviderConfiguration ??= CapacityProviderConfigurationFactory?.Build();
        result.AuthorizerConfiguration ??= AuthorizerConfigurationFactory?.Build();
    }

} // End Of Class

